import{_ as t,o as r,c as a,a4 as s}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse(`{"title":"ADR-0009 — Arbre de pages explicite et héritage de la restriction d'accès","description":"Extrait de docs/adr/0009-arbre-de-pages-et-heritage-acl.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0009 — Arbre de pages explicite et héritage de la restriction d'accès","description":"Extrait de docs/adr/0009-arbre-de-pages-et-heritage-acl.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0009-arbre-de-pages-et-heritage-acl.md","filePath":"developpeurs/adr/0009-arbre-de-pages-et-heritage-acl.md"}`),n={name:"developpeurs/adr/0009-arbre-de-pages-et-heritage-acl.md"};function i(o,e,c,d,l,u){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0009--arbre-de-pages-explicite-et-héritage-de-la-restriction-daccès" tabindex="-1">ADR-0009 — Arbre de pages explicite et héritage de la restriction d&#39;accès <a class="header-anchor" href="#adr-0009--arbre-de-pages-explicite-et-héritage-de-la-restriction-daccès" aria-label="Permalink to &quot;ADR-0009 — Arbre de pages explicite et héritage de la restriction d&#39;accès {#adr-0009--arbre-de-pages-explicite-et-héritage-de-la-restriction-daccès}&quot;">​</a></h1><p><strong>Date :</strong> 19 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §8.4 (extranet : « Restreindre l&#39;accès », « Autoriser les profils suivants », « Étendre aux pages enfants »), §9.1 (arborescence par site) ; Epic E6</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le CDC §8.4 décrit la restriction d&#39;accès d&#39;une page par trois cases, dont « Étendre aux pages enfants ». Or la table <code>pages</code> livrée par l&#39;Epic E2 ne portait <strong>aucune notion de hiérarchie</strong> : <code>slug</code> y est unique par site, sans lien de parenté. Il fallait donc décider comment le Core connaît la descendance d&#39;une page — et ce que « étendre » signifie exactement quand plusieurs niveaux déclarent leur propre règle.</p><h2 id="analyse" tabindex="-1">Analyse <a class="header-anchor" href="#analyse" aria-label="Permalink to &quot;Analyse {#analyse}&quot;">​</a></h2><p><strong>Comment connaître l&#39;arbre ?</strong> Deux options : un lien explicite (<code>parent_id</code>) ou une déduction à partir du chemin du slug (<code>services/etat-civil</code> est enfant de <code>services</code>).</p><p>La déduction est séduisante — zéro colonne, zéro migration — et disqualifiée par une seule observation : un slug est un libellé d&#39;URL. Il se change pour des raisons de référencement, de renommage de service, de fusion de communes. Une page qui perdrait son préfixe perdrait du même coup la protection héritée de son parent, sans qu&#39;aucune intention de sécurité n&#39;ait été exprimée. <strong>Une restriction d&#39;accès ne doit pas dépendre d&#39;une chaîne de caractères éditable.</strong></p><p><strong>Que se passe-t-il à la suppression d&#39;un parent ?</strong> <code>CASCADE</code> détruirait un sous-arbre entier ; <code>SET NULL</code> ferait remonter les enfants à la racine, c&#39;est-à-dire <strong>hors de la restriction héritée</strong>. Les deux transforment une suppression en moyen — volontaire ou non — d&#39;ouvrir un extranet.</p><p><strong>Quelle règle quand plusieurs niveaux déclarent ?</strong> Deux lectures possibles : l&#39;intersection des profils autorisés (le plus prudent), ou la déclaration la plus proche (le plus explicable). L&#39;intersection produit des extranets que personne ne sait plus expliquer (« j&#39;ai autorisé les associations, elles ne voient rien ») — et un droit d&#39;accès inexplicable finit par être désactivé en bloc, ce qui est le pire des résultats.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><strong><code>pages.parent_id</code></strong>, clé étrangère réflexive nullable, en <code>ON DELETE RESTRICT</code> : supprimer une page qui a des enfants est refusé par la base. Le détachement est un acte explicite (<code>POST /pages/{slug}/detach</code>), jamais l&#39;effet de bord d&#39;un <code>PUT</code> dont le champ serait absent.</li><li><strong>L&#39;héritage est le défaut</strong> : <code>inherit_to_children</code> vaut <code>true</code>. Une page enfant non configurée est protégée par son ascendant.</li><li><strong>La levée est explicite</strong> (<code>lift_inherited_restriction</code>) : aucune ligne de configuration créée par défaut n&#39;ouvre quoi que ce soit.</li><li><strong>La déclaration la plus proche gagne</strong> : une page qui pose sa propre restriction remplace celle de son ascendant, elle ne s&#39;y ajoute pas.</li><li>Un <code>inherit_to_children=false</code> parle de <strong>sa</strong> descendance : il n&#39;annule pas la décision d&#39;un ascendant.</li><li>La résolution est une <strong>fonction pure</strong> de la chaîne racine → page (<code>resolve_page_access</code>), sans base ni horloge, pour que l&#39;Epic E12 (sessions usagers) la réutilise sans la réécrire.</li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Hiérarchie déduite du chemin de slug</strong></td><td>Une restriction d&#39;accès dépendrait d&#39;un libellé d&#39;URL éditable ; un renommage rouvrirait silencieusement une branche.</td></tr><tr><td><strong><code>ON DELETE CASCADE</code> / <code>SET NULL</code> sur le parent</strong></td><td>Font d&#39;une suppression un moyen de détruire un sous-arbre ou d&#39;en lever la protection.</td></tr><tr><td><strong>Intersection des profils sur toute la chaîne</strong></td><td>Plus prudent sur le papier, mais produit des droits d&#39;accès inexplicables — donc désactivés.</td></tr><tr><td><strong>Accès effectif matérialisé sur chaque page</strong></td><td>Obligerait à recalculer un sous-arbre entier à chaque écriture, et à espérer qu&#39;aucune écriture ne soit manquée.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>L&#39;extranet du CDC §8.4 est complet dès l&#39;Epic E6 : la restriction posée sur une racine protège toute sa descendance sans configuration supplémentaire.</li><li>L&#39;accès effectif rend <strong>d&#39;où</strong> vient la restriction (<code>source_page_id</code>), ce qui rend l&#39;écran d&#39;administration explicable.</li><li>La règle est vérifiable hors base, donc testable exhaustivement.</li></ul><p><strong>Négatives</strong></p><ul><li>Une page ne peut plus être supprimée tant qu&#39;elle a des enfants : il faudra une route de réorganisation (déplacement de sous-arbre) le jour où une suppression en masse sera demandée.</li><li>L&#39;ACL par arbre <strong>complète</strong> les permissions par type de contenu ; le jour où celles-ci existeront (elles ne sont pas encore posées), il faudra documenter leur articulation plutôt que de les fusionner.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] <code>pages.parent_id</code> et <code>page_access_rules</code> posées par la migration <code>0007</code>.</li><li>[x] Epic E12 : brancher <code>EndUserSubject</code> sur une session usager réelle — la résolution d&#39;accès n&#39;aura rien à apprendre. → <strong>Close</strong> : la session usager fournit son sujet d&#39;accès (<code>app/end_users/identity.py</code>, <code>EndUserContext</code>), vérifié le 18/09/2026.</li></ul>',20)])])}const h=t(n,[["render",i]]);export{g as __pageData,h as default};
